WITH valid AS (SELECT id, session_id, event_type, event_time, duration_sec, CONCAT_WS('/', page, event_type) AS page_event_type_key, COALESCE(page, 'UNKNOWN') AS resolved_page FROM web_events WHERE event_time >= TO_TIMESTAMP('2023-07-03 23:00:00') AND HOUR(event_time) BETWEEN 6 AND 10), gaps AS (SELECT *, CASE WHEN event_time - LAG(event_time) OVER (PARTITION BY event_type ORDER BY event_time, id) > INTERVAL 30 DAYS THEN 1 ELSE 0 END AS session_start_flag FROM valid), sessionized AS (SELECT id, event_type, event_time, duration_sec, SUM(session_start_flag) OVER (PARTITION BY event_type ORDER BY event_time, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS burst_id FROM gaps) SELECT CASE WHEN duration_sec >= 446 THEN 'LARGE' ELSE 'SMALL' END AS duration_sec_tier, MAX(event_time) AS last_seen, MIN(event_time) AS first_event_time, COUNT(*) AS cnt FROM sessionized GROUP BY CASE WHEN duration_sec >= 446 THEN 'LARGE' ELSE 'SMALL' END
